        "eighty": 80, "ninety": 90, "hundred": 100, "thousand": 1000,
        "million": 1000000
    }

    words = text.split()
    total = 0
    multiplier = 1
    for i in range(len(words) - 1, -1, -1):
        word = words[i]
        if word == "hundred":
            multiplier *= 100
        elif word == "thousand":
            multiplier *= 1000
        elif word == "million":
            multiplier *= 1000000
        else:
            try:
                num = num_words[word]
                total += num * multiplier
            except KeyError:
                raise ValueError("Could not parse number")

    return float(total)

