        "fifty": 50, "sixty": 60, "seventy": 70, "eighty": 80, "ninety": 90,
    }

    multiplier = 1
    total = 0
    parts = text.split()

    for i, part in enumerate(parts):
        part_lower = part.lower()
        if part_lower == 'hundred':
            multiplier = 100
        elif part_lower == 'thousand':
            multiplier = 1000
