    """Extracts a monetary amount from a user-typed string."""
    text = text.strip()
    if not text:
        raise ValueError("Cannot parse empty string")

    text = text.replace("$", "")
    text = text.replace(",", "")

    if text.startswith("-"):
        sign = -1
        text = text[1:]
    else:
        sign = 1

    if text.endswith("dollars") or text.endswith("dollar"):
        try:
            amount = float(text[:-len("dollars")] if text.endswith("dollars") else text[:-len("dollar")])
        except ValueError:
            raise ValueError("Cannot parse amount")
    elif re.match(r"^[a-z]+$", text):  # Handle written number only
      try:
          amount = written_number_to_float(text)
      except ValueError:
          raise ValueError("Cannot parse amount")

    else:
        try:
            amount = float(text)
        except ValueError:
            raise ValueError("Cannot parse amount")

    return sign * amount


def written_number_to_float(text):
    """Converts a written number to a float."""
    numbers = {
        "zero": 0.0, "one": 1.0, "two": 2.0, "three": 3.0, "four": 4.0,
        "five": 5.0, "six": 6.0, "seven": 7.0, "eight": 8.0, "nine": 9.0,
        "ten": 10.0, "eleven": 11.0, "twelve": 12.0, "thirteen": 13.0,
        "fourteen": 14.0, "fifteen": 15.0, "sixteen": 16.0, "seventeen": 17.0,
        "eighteen": 18.0, "nineteen": 19.0, "twenty": 20.0,
        "thirty": 30.0, "forty": 40.0, "fifty": 50.0, "sixty": 60.0,
        "seventy": 70.0, "eighty": 80.0, "ninety": 90.0,
        "hundred": 100.0, "thousand": 1000.0, "million": 1000000.0
    }

    total = 0.0
    parts = text.split()

    i = 0
    while i < len(parts):
        part = parts[i]
        if part in numbers:
            if i + 1 < len(parts) and parts[i+1] == "hundred":
                if i + 2 < len(parts) and parts[i+2] in numbers:
                    total += numbers[part] * numbers["hundred"] + numbers[parts[i+2]]
                    i+=3
                else:
                   total += numbers[part] * numbers["hundred"]
                   i+=2
            elif i + 1 < len(parts) and parts[i+1] in ("thousand", "million"):
               total += numbers[part] * numbers[parts[i+1]]
               i+=2

            else:
                total += numbers[part]
                i += 1

        else:
            raise ValueError("Cannot parse amount")


    return total

