    text = text.strip()

    if not text:
        raise ValueError("Cannot parse an empty string")

    text = text.replace("$", "")
    text = text.replace(",", "")

    if re.search(r"\bdollars?\b$", text, re.IGNORECASE):
        amount_str = text[:-len("dollars") if text.lower().endswith("dollars") else -len("dollar")]
        try:
            return float(amount_str)
        except ValueError:
            raise ValueError("Could not parse amount")

    if "-" in text and text[0] == "-":
        amount_str = text[1:]
        try:
            return -float(amount_str)
        except ValueError:
            raise ValueError("Could not parse amount")

    if "." not in text:
        try:
            return float(text)
        except ValueError:
            try:
                num = written_number(text)
                return float(num)
            except ValueError:
                raise ValueError("Could not parse amount")
    else:
        try:
             return float(text)
        except ValueError:
            try:
                num = written_number(text.split(".")[0])
                decimal_part = float("." + text.split(".")[1])
                return num + decimal_part
            except ValueError:
                 raise ValueError("Could not parse amount")


def written_number(text):
    """Converts a written number to its numerical value."""
    numbers = {
        "zero": 0, "one": 1, "two": 2, "three": 3, "four": 4, "five": 5,
        "six": 6, "seven": 7, "eight": 8, "nine": 9, "ten": 10,
        "eleven": 11, "twelve": 12, "thirteen": 13, "fourteen": 14,
        "fifteen": 15, "sixteen": 16, "seventeen": 17, "eighteen": 18,
        "nineteen": 19, "twenty": 20, "thirty": 30, "forty": 40,
        "fifty": 50, "sixty": 60, "seventy": 70, "eighty": 80, "ninety": 90,
    }

    if text.lower() in numbers:
        return numbers[text.lower()]

    if text.lower() == "hundred":
        return 100

    if text.lower() == "thousand":
        return 1000

    if text.lower() == "million":
        return 1000000

    parts = text.lower().split()
    total = 0
    i = 0
    while i < len(parts):
        if parts[i] in numbers:
            total += numbers[parts[i]]
            i += 1
        elif parts[i] == "hundred":
            if i + 1 < len(parts) and parts[i+1] in numbers:
                total += 100 * numbers[parts[i+1]]
                i+=2
            else:
                 total += 100
                 i +=1
        elif parts[i] == "thousand":
             total += 1000 * total
             i+=1
        elif parts[i] == "million":
            total += 1000000* total
            i+=1
        else:
          raise ValueError("Could not parse written number")

    return total

import re

def parse_amount(text: str) -> float:
    """Extracts a monetary amount from a user-typed string."""
    text = text.strip()

    if not text:
        raise ValueError("Cannot parse empty string")

    text = text.replace("$", "")
    text = text.replace(",", "")

    if text.endswith("dollars") or text.endswith("dollar"):
        try:
            amount = float(text[:-len("dollars")] if text.endswith("dollars") else text[:-len("dollar")])
        except ValueError:
            raise ValueError("Invalid amount format")
        return amount

    if re.match(r"^-?\d+(\.\d+)?$", text):
        try:
            return float(text)
        except ValueError:
            raise ValueError("Invalid number format")

    number_words = {
        "zero": 0, "one": 1, "two": 2, "three": 3, "four": 4, "five": 5,
        "six": 6, "seven": 7, "eight": 8, "nine": 9, "ten": 10, "eleven": 11,
        "twelve": 12, "thirteen": 13, "fourteen": 14, "fifteen": 15, "sixteen": 16,
        "seventeen": 17, "eighteen": 18, "nineteen": 19, "twenty": 20,
        "thirty": 30, "forty": 40, "fifty": 50, "sixty": 60, "seventy": 70,
        "eighty": 80, "ninety": 90, "hundred": 100, "thousand": 1000, "million": 1000000
    }

    words = text.lower().split()
    total = 0
    multiplier = 1
    negative = False

    if words[0] == "-":
        negative = True
        words.pop(0)

    for i, word in enumerate(words):
        if word == "hundred":
            if i + 1 < len(words) and words[i+1] == "thousand":
                multiplier = 1000
                i += 1
            else:
                total += 100 * multiplier
        elif word == "thousand":
            multiplier = 1000
        elif word == "million":
            multiplier = 1000000
        elif word in number_words:
            total += number_words[word] * multiplier
            if i + 1 < len(words) and words[i+1] == "hundred":
                multiplier = 1
            else:
                multiplier = 1

    if negative:
        return -float(total)
