    else:
        negative = False

    if text.endswith("dollars") or text.endswith("dollar"):
        text = text[:-len("dollars")] if text.endswith("dollars") else text[:-len("dollar")]

    try:
        amount = float(text)
    except ValueError:
        # Try parsing as written number
        try:
            amount = parse_written_number(text)
        except ValueError:
            raise ValueError(f"Cannot parse amount: {text}")

    return float(amount) if not negative else -float(amount)


def parse_written_number(text: str) -> float:
    numbers = {
        "zero": 0, "one": 1, "two": 2, "three": 3, "four": 4,
        "five": 5, "six": 6, "seven": 7, "eight": 8, "nine": 9,
        "ten": 10, "eleven": 11, "twelve": 12, "thirteen": 13,
        "fourteen": 14, "fifteen": 15, "sixteen": 16, "seventeen": 17,
        "eighteen": 18, "nineteen": 19, "twenty": 20, "thirty": 30,
        "forty": 40, "fifty": 50, "sixty": 60, "seventy": 70,
        "eighty": 80, "ninety": 90, "hundred": 100, "thousand": 1000,
        "million": 1000000
    }

    tokens = text.split()
    total = 0
    multiplier = 1
    for token in reversed(tokens):
        if token in numbers:
            total += numbers[token] * multiplier
            multiplier *= 100 if token == "hundred" else 1000 if token == "thousand" else 1000000 if token == "million" else 1
        else:
            raise ValueError(f"Cannot parse written number: {text}")

    return float(total)

