                      total += num * 1000
                      multiplier = 1
                  except ValueError:
                     raise ValueError("Invalid amount format")
             else:
                 total += multiplier * 1000
                 multiplier = 1

        elif word == "million":
            if i > 0 and words[i-1] != "thousand" and words[i-1] != "hundred":
                try:
                    num = written_number_to_float(words[i-1])
                    total += num * 1000000
                    multiplier = 1
                except ValueError:
                  raise ValueError("Invalid amount format")

            else :
                 total += multiplier * 1000000
                 multiplier = 1



        else:
            try:
                num = written_numbers[word]
                total += num * multiplier
                multiplier = 1
            except KeyError:
