        word = words[i]
        if word == "hundred":
            if i > 1:
                prev_num = parse_number(words[i - 2]) if i > 1 else 1.0
                amount += prev_num * 100
            else:
                amount += 100
            i += 1
        elif word == "thousand":
            if i > 1:
                prev_num = parse_number(words[i - 2]) if i > 1 else 1.0
                amount += prev_num * 1000
            else:
                amount += 1000
            i += 1
        elif word == "million":
             if i > 1:
                prev_num = parse_number(words[i - 2]) if i > 1 else 1.0
                amount += prev_num * 1000000
             else:
                amount += 1000000

             i+=1
        else:
            try:
                number = parse_number(word)
                amount += number
                i += 1
            except ValueError:
                raise ValueError("Invalid amount format")

    return amount

