        "eighteen": 18, "nineteen": 19, "twenty": 20, "thirty": 30,
        "forty": 40, "fifty": 50, "sixty": 60, "seventy": 70, "eighty": 80,
        "ninety": 90, "hundred": 100, "thousand": 1000, "million": 1000000
    }

    words = text.split()
    total = 0
    multiplier = 1

    for i in range(len(words) - 1, -1, -1):
        word = words[i].lower()
        if word == "hundred":
            if i > 0 and words[i-1] != "thousand" and words[i-1] != "million":
                multiplier = 100
            else:
                multiplier = 1

        elif word == "thousand":
            multiplier = 1000
        elif word == "million":
            multiplier = 1000000
        else:
            try:
                num = numbers[word]
                total += num * multiplier
                if i > 0 and words[i - 1] == 'hundred':
                  multiplier = 1

            except KeyError:
              raise ValueError(f"Unknown word: {word}")


    return total
